const body = $json.body ?? $json;
const phone = String(body.phone ?? '').replace(/[^\d+]/g, '');

if (!phone || phone.length < 8) {
  return [{ json: { ok: false, statusCode: 400, message: 'Número inválido.' } }];
}

const staticData = $getWorkflowStaticData('global');
staticData.subscribers = Array.isArray(staticData.subscribers) ? staticData.subscribers : [];

const existing = staticData.subscribers.find((subscriber) => subscriber.phone === phone);

if (existing) {
  existing.updatedAt = new Date().toISOString();
  existing.active = true;
} else {
  staticData.subscribers.push({
    phone,
    country: 'ar',
    market: 'cripto',
    active: true,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });
}

return [{
  json: {
    ok: true,
    statusCode: 200,
    message: 'Suscripción registrada para alertas de dólar cripto.',
    subscribers: staticData.subscribers.length,
  }
}];

const staticData = $getWorkflowStaticData('global');
const subscribers = (staticData.subscribers ?? []).filter((subscriber) => subscriber.active && subscriber.country === 'ar');

if (subscribers.length === 0) {
  return [];
}

const rows = $input.all().map((item) => item.json);
const cutoff = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
const recent = rows
  .map((row) => ({ ...row, date: new Date(row.fecha) }))
  .filter((row) => row.date >= cutoff && Number.isFinite(Number(row.venta)))
  .sort((a, b) => a.date.getTime() - b.date.getTime());

if (recent.length === 0) {
  return [];
}

const latest = recent[recent.length - 1];
const maxSell = Math.max(...recent.map((row) => Number(row.venta)));
const latestSell = Number(latest.venta);
const latestDateKey = latest.date.toISOString().slice(0, 10);
const alertKey = `${latestDateKey}-${latestSell}`;

if (latestSell < maxSell || staticData.lastMonthlyHighAlertKey === alertKey) {
  return [];
}

staticData.lastMonthlyHighAlertKey = alertKey;

const formattedRate = new Intl.NumberFormat('es-AR', {
  style: 'currency',
  currency: 'ARS',
  maximumFractionDigits: 2,
}).format(latestSell);

const message = `🚨 Dólar cripto en máximo de 30 días\n\nVenta actual: ${formattedRate}\nFecha: ${latestDateKey}\n\nCalculadora de Sueldo USD`;

return subscribers.map((subscriber) => ({
  json: {
    phone: subscriber.phone,
    message,
    latestSell,
    latestDateKey,
  }
}));
